; ----------------------------------------------------------------------
; WHEN THE BOSS DIES, THE SCREEN GOES DARK BY EATING THE VRAM
; The cartridge does not clear the screen to end the stage: it eats it. It
; brings blocks of 0x200 bytes down from VRAM to 0xEA00, ANDs them with a
; mask and sends them back up. First it makes one pass over the COLOUR
; table (which in this cartridge lives at VRAM 0x0000) with mask 0xF0, and
; then repeats the pass EIGHT times over the PATTERN table (0x2000) with
; 0xFE, 0xFC, 0xF8... down to 0x00, also rotating the mask three bits per
; byte, so that the black comes in crumbled and not in rows.
; Bank 2 calls it from two different bosses, and when it is done it sets
; 0xE1A3.
; ----------------------------------------------------------------------
switch_off_screen:		; The four steps of the fade: eat the colours, eat the patterns, clear 0xED00 and report back
	ld hl,0e1a0h		;a6c0   ; 0xE1A0: which step the fade is on
	ld a,(hl)			;a6c3
	dec a			;a6c4
	jr z,eat_patterns		;a6c5
	dec a			;a6c7
	jr z,clear_buffer		;a6c8
	dec a			;a6ca
	jp z,report_done		;a6cb
	ld a,(0e1d0h)		;a6ce   ; If nothing else is already playing, sound 0x3E
	and a			;a6d1
	ld a,03eh		;a6d2
	call z,049deh		;a6d4
	xor a			;a6d7   ; 0xE1A3 to zero: not finished yet
	ld (0e1a3h),a		;a6d8
	inc l			;a6db   ; 0xE1A1 to zero: starting from the first row
	ld (hl),a			;a6dc
	inc l			;a6dd
	ld (hl),0f0h		;a6de   ; 0xE1A2: the mask starts at 0xF0
eat_background_colours:		; A whole pass over the colour table, 0x40 rows at a time
	ld a,(0e1a1h)		;a6e0   ; 0xE1A1: which row it is on
	cp 040h		;a6e3   ; The first third does not reach 0x1000
	jr c,L_A6F3		;a6e5
	cp 080h		;a6e7
	jr nc,L_A6ED		;a6e9
	ld a,044h		;a6eb
L_A6ED:
	ld de,01000h		;a6ed   ; The third third of colours
	call eat_chunk		;a6f0
L_A6F3:
	ld de,00800h		;a6f3   ; The second...
	call chunk_with_current_mask		;a6f6
	ld de,00000h		;a6f9   ; ...and the first
	call chunk_with_current_mask		;a6fc
	ld hl,0e1a1h		;a6ff
	ld a,(hl)			;a702
	add a,040h		;a703   ; 0x40 more rows
	ld (hl),a			;a705
	jr nz,eat_background_colours		;a706
	dec l			;a708
	inc (hl)			;a709   ; Once all the way round, step 1
	inc l			;a70a
	inc l			;a70b
	ld (hl),0feh		;a70c   ; And the pattern mask starts at 0xFE
	ret			;a70e
eat_patterns:		; The same pass, but over the pattern table and removing one more bit each round
	ld a,(0e1a1h)		;a70f
	cp 040h		;a712   ; Below row 0x40, only two thirds
	jr c,L_A722		;a714
	cp 080h		;a716   ; And row 0x44 takes fewer bytes
	jr nc,L_A71C		;a718
	ld a,044h		;a71a
L_A71C:
	ld de,03000h		;a71c   ; The third third of patterns
	call eat_chunk		;a71f
L_A722:
	ld de,02800h		;a722   ; The second...
	call chunk_with_current_mask		;a725
	ld de,02000h		;a728   ; ...and the first
	call chunk_with_current_mask		;a72b
	ld hl,0e1a1h		;a72e
	ld a,(hl)			;a731
	add a,040h		;a732
	ld (hl),a			;a734
	ret nz			;a735   ; Until it has gone all the way round, nothing
	inc l			;a736
	ld a,(hl)			;a737
	and a			;a738
	jr z,L_A73E		;a739
	sla (hl)		;a73b   ; One bit fewer in the mask
	ret			;a73d
L_A73E:
	ld a,002h		;a73e   ; With the mask at zero everything is black: step 2
	ld (0e1a0h),a		;a740
	ret			;a743
clear_buffer:		; The 0x2C0 bytes of 0xED00 to zero, and on to step 3
	ld hl,0ed00h		;a744   ; 0xED00 onwards...
	ld de,0ed01h		;a747
	ld bc,002bfh		;a74a   ; ...0x2C0 bytes to zero
	ld (hl),000h		;a74d
	ldir		;a74f
	ld a,003h		;a751   ; And step 3
	ld (0e1a0h),a		;a753
	ret			;a756
report_done:		; When the sound stops, 0xE1A3 is set and bank 2 takes the boss as dead
	ld a,(0e012h)		;a757   ; 0xE012: not until the sound stops
	and a			;a75a
	ret nz			;a75b
	ld a,001h		;a75c   ; 0xE1A3 to one: bank 2 can now carry on
	ld (0e1a3h),a		;a75e
	ret			;a761
chunk_with_current_mask:		; Comes in with the current row in 0xE1A1
	ld a,(0e1a1h)		;a762
eat_chunk:		; Brings 0x200 bytes down from VRAM to 0xEA00, applies the mask to them and sends them back up
	ld bc,00200h		;a765   ; Half a kilobyte at a time
	cp 044h		;a768   ; Two rows take fewer: 0x44...
	jr nz,L_A76F		;a76a
	ld bc,001e0h		;a76c
L_A76F:
	cp 0c0h		;a76f   ; ...and 0xC0
	jr nz,L_A776		;a771
	ld bc,001b0h		;a773
L_A776:
	ld l,a			;a776   ; The row times eight: the byte where it starts
	ld h,000h		;a777
	add hl,hl			;a779
	add hl,hl			;a77a
	add hl,hl			;a77b
	add hl,de			;a77c
	push hl			;a77d
	ld de,0ea00h		;a77e   ; 0xEA00: the block comes down here
	push bc			;a781
	call 00059h		;a782   ; BIOS LDIRMV - Block transfers to memory from VRAM
	pop bc			;a785
	push bc			;a786
	ld hl,0ea00h		;a787
	ld a,(0e1a2h)		;a78a   ; 0xE1A2: this round's mask
	ld e,a			;a78d
	call apply_mask		;a78e
	pop bc			;a791
	pop hl			;a792
	ld de,0ea00h		;a793
	jp 04960h		;a796   ; And the block, bitten, goes back to VRAM
apply_mask:		; In the first step the mask is the same for every byte; in the rest it rotates three bits per byte
	ld a,(0e1a0h)		;a799
	and a			;a79c
	jr nz,rotating_mask		;a79d
fixed_mask:		; AND with the same mask byte by byte
	ld a,(hl)			;a79f   ; AND with the mask, byte by byte
	and e			;a7a0
	ld (hl),a			;a7a1
	inc hl			;a7a2
	dec bc			;a7a3   ; Half a kilobyte
	ld a,b			;a7a4
	or c			;a7a5
	jr nz,fixed_mask		;a7a6
	ret			;a7a8
rotating_mask:		; Three bits of rotation per byte: the black comes in crumbled
	ld a,(hl)			;a7a9   ; The same mask, rotated three bits...
	and e			;a7aa
	ld (hl),a			;a7ab
	inc hl			;a7ac
	rrc e		;a7ad
	rrc e		;a7af
	rrc e		;a7b1
	dec bc			;a7b3   ; ...on every byte of the block
	ld a,b			;a7b4
	or c			;a7b5
	jr nz,rotating_mask		;a7b6
	ret			;a7b8

; ----------------------------------------------------------------------
; EACH ENEMY TYPE HAS TWO ROUTINES, AND ALMOST ALL OF THEM ARE HERE
; An object boils down to one number, its type, from 1 to 0x1F. That
; number drives two tables: the one at p00:0x5DFD, which says who moves it
; every frame, and the one at p01:0x6B46, which says who finishes building
; it when it is born. Of the thirty-one types, TWENTY have at least one of
; their two routines here, and SIXTEEN have both; that is why
; 0xA7B9..0xB537 is the longest stretch of code in the cartridge.
; ----------------------------------------------------------------------
finish_type_16:		; No speed and bit 1 of byte 27 cleared
	res 1,(ix+01bh)		;a7b9
	jp 09510h		;a7bd
finish_type_17:		; The same, and byte 23 to one
	res 1,(ix+01bh)		;a7c0
	ld (ix+017h),001h		;a7c4
	jp 09510h		;a7c8
finish_type_18:		; The same, and byte 23 to eight
	res 1,(ix+01bh)		;a7cb
	ld (ix+017h),008h		;a7cf
	jp 09510h		;a7d3
finish_type_19:		; Only the speeds to zero
	jp 09510h		;a7d6
move_types_17_and_18:		; They move with the scroll and, when they go off screen, break the capsule chain
	call 09251h		;a7d9
	ret nc			;a7dc
	jr L_A81C		;a7dd
move_type_1A:		; Moves with the scroll and, when its count runs out, turns into the type noted in byte 24
	call 09251h		;a7df   ; Moves with the scroll
	jp c,left_unclaimed		;a7e2   ; Going off the edge is handled elsewhere
	ld a,(ix+004h)		;a7e5
	or a			;a7e8
	jp z,L_A7EF		;a7e9
	dec (ix+004h)		;a7ec
L_A7EF:
	dec (ix+002h)		;a7ef   ; Byte 2: the frames it has left like this
	ret nz			;a7f2
	ld a,(ix+018h)		;a7f3   ; Byte 24 says what it turns into
	cp 016h		;a7f6   ; With 0x16 it does not turn into anything: it switches off
	jp z,05fa5h		;a7f8
	dec (ix+017h)		;a7fb   ; And byte 23 counts how many times it can
	jp z,05fa5h		;a7fe
	ld (ix+000h),a		;a801   ; The new type, in its place
	ld (ix+00bh),001h		;a804   ; Byte 11 to one: drawn with characters
	ld (ix+00ch),038h		;a808   ; And character 0x38
	set 0,(ix+01bh)		;a80c
	ld a,(ix+019h)		;a810   ; Byte 25 reloads the count
	ld (ix+004h),a		;a813
	ret			;a816
left_unclaimed:		; When it leaves through the edge, the capsule chain starts over
	ld a,(ix+017h)		;a817
	dec a			;a81a
	ret z			;a81b
L_A81C:
	xor a			;a81c
	ld (0e128h),a		;a81d   ; 0xE128 to zero: the next capsule pays one point again
	ret			;a820
finish_type_3:		; Down four, two to the left, and its path curves
	ld de,00400h		;a821   ; Four points per frame downwards
	call 06cbfh		;a824
	call 09530h		;a827   ; And that same figure as horizontal acceleration
	ld de,0fe00h		;a82a   ; Two to the left
	call 06cc6h		;a82d
	ld de,0ff80h		;a830   ; With half a point of vertical acceleration
	jp 09522h		;a833
move_type_3:		; Fires, changes drawing and keeps curving until the speed equals the acceleration
	call 09235h		;a836   ; Fires without aiming
	call animate_type_3		;a839   ; Changes drawing
	call 0953ch		;a83c   ; And the curve: acceleration plus speed
	call 09564h		;a83f
	call z,09519h		;a842
	ret			;a845
animate_type_3:		; Eight drawings, one every eight frames, there and back
	ld bc,00708h		;a846
	ld hl,0a84fh		;a849
	jp 095d1h		;a84c

; ----------------------------------------------------------------------
; DATA table_A84F: Eight bytes read by 0xA849: there and back (0x8C, 0x90,
;   0x94, 0x98, 0x9C, 0x98, 0x94, 0x90).
;   0xa84f..0xa857  (8 bytes)
DATA_table_A84F:
	defb 08ch,090h,094h,098h,09ch,098h,094h,090h	; a84f  ........

; ======================================================================
; CODE 0xa857..0xa933  (220 bytes)
; ======================================================================


finish_type_4:		; No vertical speed and one and a half points to the left
	ld de,00000h		;a857
	call 06cbfh		;a85a
	ld de,0fe80h		;a85d
	jp 06cc6h		;a860

; ----------------------------------------------------------------------
; THE ENEMY TILTS TOWARDS WHERE IT FLIES
; Type 4 has three drawings (0xB0 level, 0xB4 tilted up and 0xB8 tilted
; down) and the right one is picked here at the same time as the speed: if
; the ship is above it, it takes 0xB4 and climbs; if the ship is below it,
; 0xB8 and it descends; and once it is on the ship's row, 0xB0 and it just
; moves forward. Drawing and heading come from the same place, so they
; never contradict each other.
; ----------------------------------------------------------------------
move_type_4:		; Gets level with the ship and tilts towards where it is going
	call 09235h		;a863
	ld a,(0e204h)		;a866   ; The ship's row minus its own
	sub (ix+004h)		;a869
	push af			;a86c
	add a,003h		;a86d
	cp 007h		;a86f   ; Within seven it is already on its row
	jr c,L_A88A		;a871
	pop af			;a873
	jr c,L_A880		;a874
	ld a,0b8h		;a876   ; Ship below: drawing 0xB8 and one and a half points downwards
	ld de,0fe80h		;a878
	ld bc,00180h		;a87b
	jr L_A89E		;a87e
L_A880:
	ld a,0b4h		;a880   ; Above: drawing 0xB4 and one and a half points upwards
	ld de,0fe80h		;a882
	ld bc,0fe80h		;a885
	jr L_A89E		;a888
L_A88A:
	pop af			;a88a
	ld a,(0e206h)		;a88b   ; Already on its row: the column is checked
	sub (ix+006h)		;a88e
	ld de,0fd00h		;a891   ; With the ship ahead, three points to the left
	jr c,L_A899		;a894
	ld de,0fe80h		;a896   ; And otherwise, one and a half
L_A899:
	ld bc,00000h		;a899   ; No vertical speed: drawing 0xB0
	ld a,0b0h		;a89c
L_A89E:
	ld (ix+00ch),a		;a89e   ; The chosen drawing, to byte 12
	call 06cc6h		;a8a1
	ld d,b			;a8a4
	ld e,c			;a8a5
	jp 06cbfh		;a8a6
finish_type_2:		; Still, and four points to the left
	call 09510h		;a8a9
	ld de,0fc00h		;a8ac
	jp 06cc6h		;a8af

; ----------------------------------------------------------------------
; THE ENEMY THAT TURNS BACK
; Type 2 does not just cross the screen: it comes in from the right, and on
; reaching column 0x81 (0x7F if it is in the bottom half) it curves towards
; the centre and goes back; at 0x9F it stops and heads left again, this
; time as far as 0x51; and when it finally gets level with the ship, it
; stops climbing and descending and flies straight on.
; These are four steps counted in byte 1.
; ----------------------------------------------------------------------
move_type_2:		; The four steps of the turn: to 0x81, back to 0x9F, to 0x51, and straight on once level with the ship
	ld a,(0e111h)		;a8b2   ; From difficulty 8 onwards, it also fires
	cp 008h		;a8b5
	call nc,09235h		;a8b7
	call animate_type_2		;a8ba   ; Four drawings, one every four frames
	ld a,(ix+001h)		;a8bd   ; Byte 1: which step it is on
	dec a			;a8c0
	jr z,back_to_column_9F		;a8c1
	dec a			;a8c3
	jr z,again_to_51		;a8c4
	dec a			;a8c6
	jr z,level_with_ship		;a8c7
	dec a			;a8c9
	ret z			;a8ca
	ld bc,0817fh		;a8cb   ; The limit of step 0: 0x81 at the top and 0x7F at the bottom
L_A8CE:
	ld a,(ix+004h)		;a8ce   ; Above row 0x50...
