; ----------------------------------------------------------------------
; STAGE 7 RUNS ON A SCRIPT, AND EACH APPEARANCE FITS IN ONE WORD
; The other stages release enemies in bursts; the seventh has them WRITTEN
; one by one in the list at 0xAF3F, forty-three appearances in eighty-six
; bytes. Each one is a single, tightly packed word: the low byte and bit 0
; of the high byte are the distance (nine bits) at which it appears, bits 1
; and 2 of the high byte are the variant, and the top five, the row. The
; list is walked with a cursor at 0xE968 and ends at 0xFFFF.
; ----------------------------------------------------------------------
advance_script:		; Skips in one go all the appearances that are already behind the distance travelled
	ld a,(0e061h)		;aedf   ; Only stage 7 has a script
	cp 007h		;aee2
	ret nz			;aee4
	call spawn_this_appearance		;aee5
	jp z,advance_script		;aee8   ; As long as they keep falling due, they keep being taken out
	ret c			;aeeb   ; Once past the distance of the one that is due, it stops
	ld hl,0e968h		;aeec
	inc (hl)			;aeef   ; And the ones left behind are skipped
	jp advance_script		;aef0
check_script:		; On every step with a new column, releases all the appearances that fall at this distance
	ld a,(0e061h)		;aef3   ; Only stage 7
	cp 007h		;aef6
	ret nz			;aef8
	ld a,(0e100h)		;aef9   ; And only on steps with a new column
	and a			;aefc
	ret z			;aefd
	ld a,0f8h		;aefe   ; 0xEC04 to 0xF8: they all come in from the right
	ld (0ec04h),a		;af00
spawn_due_ones:		; One after another as long as they match
	call spawn_this_appearance		;af03
	jp z,spawn_due_ones		;af06
	ret			;af09
spawn_this_appearance:		; If the list's distance is the current one, moves the cursor on and releases the enemy
	call is_this_the_distance		;af0a   ; Without a match, there is nothing to do
	ret nz			;af0d
	ld hl,0e968h		;af0e
	inc (hl)			;af11   ; One appearance fewer in the list
	ld a,c			;af12   ; The top five bits: the row
	and 0f8h		;af13
	ld e,a			;af15
	ld a,(0ec04h)		;af16   ; With the column below 0x80 nothing is released
	cp 080h		;af19
	jr nc,spawn_type_0D		;af1b
	xor a			;af1d
	ret			;af1e
spawn_type_0D:		; The column, the row and the variant already unpacked
	ld d,a			;af1f
	ld a,c			;af20   ; Bits 1 and 2: the variant
	rra			;af21
	and 003h		;af22
	ld c,a			;af24
	ld a,00dh		;af25   ; Type 0x0D
	call 06a72h		;af27
	xor a			;af2a
	ret			;af2b
is_this_the_distance:		; Unpacks the script word and compares its nine bits of distance with the distance travelled
	ld hl,0af3fh		;af2c   ; The word that is due from the list
	ld a,(0e968h)		;af2f
	call 047aeh		;af32
	ld c,d			;af35   ; The high byte is saved whole...
	ld a,d			;af36
	and 001h		;af37   ; ...and of it only bit 0 is distance
	ld d,a			;af39
	ld hl,(0e063h)		;af3a   ; DCOMPR against the distance travelled
	rst 20h			;af3d
	ret			;af3e

