type_0D_leaves:		; Step 2, drawing 0xDC in colour 0x0D and one point to the left
	ld (ix+001h),002h		;afa8   ; Step 2: it is already leaving
	ld (ix+00ch),0dch		;afac   ; Drawing 0xDC in colour 0x0D
	ld (ix+00dh),00dh		;afb0
