; ----------------------------------------------------------------------
; THE FAN OF THREE SHOTS
; This enemy does not fire one shot: it fires three, spread in a fan around
; the ship. The angle to the ship is measured (0xEC18) and only its high
; nibble is kept, which gives sixteen directions all the way round, and
; three shots are released with that number, with the next one and with
; the one before. The two speeds of each direction are worked out in
; advance in the table at 0xB26A: four bytes per direction, two words.
; ----------------------------------------------------------------------
release_fan:		; Measures the angle to the ship and releases three shots: the one at that angle, the next one and the one before
	ld a,(ix+002h)		;b1fc   ; Its row and its column, plus 0x10: from the centre of the enemy
	add a,010h		;b1ff
	ld e,a			;b201
	ld a,(ix+003h)		;b202
	add a,010h		;b205
	ld d,a			;b207
	call 066d5h		;b208   ; From that comes the angle to the ship, in 0xEC18
	ld c,000h		;b20b   ; The middle one...
	call insert_shot		;b20d
	ld c,001h		;b210   ; ...the next one...
	call insert_shot		;b212
	ld c,0ffh		;b215   ; ...and the one before
insert_shot:		; Looks for a free slot among the ten at 0xE500 and fills it with the position and with the speed for that direction
	ld a,(0ec18h)		;b217   ; The high nibble of the angle: sixteen directions
	rra			;b21a
	rra			;b21b
	rra			;b21c
	rra			;b21d
	add a,c			;b21e   ; Plus the fan offset
	and 00fh		;b21f
	ld (0ec00h),a		;b221
	ld hl,0e500h		;b224   ; The ten slots at 0xE500, 0x20 apart
	ld de,00020h		;b227
	ld b,00ah		;b22a
	xor a			;b22c
L_B22D:
	cp (hl)			;b22d   ; The first one with its first byte at zero
	jr z,L_B234		;b22e
	add hl,de			;b230
	djnz L_B22D		;b231
	ret			;b233
L_B234:
	ld (hl),001h		;b234   ; Taken
	inc l			;b236
	inc l			;b237
	inc l			;b238
	inc l			;b239
	ld a,(ix+002h)		;b23a   ; The enemy's row plus 0x10
	add a,010h		;b23d
	ld (hl),a			;b23f
	inc l			;b240
	inc l			;b241
	ld a,(ix+003h)		;b242   ; And its column
	add a,010h		;b245
	ld (hl),a			;b247
	ld de,0b26ah		;b248   ; The table at 0xB26A: four bytes per direction
	ld a,(0ec00h)		;b24b
