	ex de,hl			;b25a
	ld (hl),000h		;b25b
	inc l			;b25d
	ld (hl),088h		;b25e   ; Drawing 0x88 in colour 9
	inc l			;b260
	ld (hl),009h		;b261
	ld de,0000eh		;b263
	add hl,de			;b266
	ld (hl),001h		;b267   ; And byte 0x12 to one
