	ld a,(ix+00ch)		;bdc9
	xor 004h		;bdcc   ; Bit 2 of the character: two drawings
	ld (ix+00ch),a		;bdce
	ret			;bdd1

; ----------------------------------------------------------------------
; THE BACKGROUND THAT MOVES WITHOUT SPENDING A SINGLE SPRITE
; No object moves here: what changes is the DRAWING of three characters
; (0xF6, 0xF7 and 0xF8), by rewriting their eight bytes in VRAM. The table
; at 0xBE19 holds six drawings for each of them, and each one goes its own
; way: how long its drawing lasts is drawn by lot by the R register,
; between 8 and 0x17 frames. Since the background is made with those three
; characters, all the cells that use them move at once at no cost.
; ----------------------------------------------------------------------
animate_three_characters:		; Rewrites in VRAM the eight bytes of characters 0xF6, 0xF7 and 0xF8
	call animate_seven_cells		;bdd2
	ld hl,0e700h		;bdd5   ; Character 0xF6, with its count at 0xE700
	ld de,0be19h		;bdd8
	ld c,0f6h		;bddb
	call animate_character		;bddd
	ld hl,0e702h		;bde0   ; 0xF7, with its own at 0xE702
	ld de,0be1fh		;bde3
	ld c,0f7h		;bde6
	call animate_character		;bde8
	ld hl,0e704h		;bdeb   ; And 0xF8, at 0xE704
	ld de,0be25h		;bdee
	ld c,0f8h		;bdf1
animate_character:		; When the count runs out, moves on to the next of the six drawings and uploads it to VRAM
	dec (hl)			;bdf3   ; The frames this drawing has left
	ret nz			;bdf4
	ld a,r		;bdf5   ; The R register: between 8 and 0x17 frames
	and 00fh		;bdf7
	add a,008h		;bdf9
	ld (hl),a			;bdfb
	dec hl			;bdfc
	ld a,(hl)			;bdfd   ; The next drawing...
	inc a			;bdfe
	cp 006h		;bdff   ; ...of the six, round and round
	jr c,L_BE04		;be01
	xor a			;be03
L_BE04:
	ld (hl),a			;be04
	call 04062h		;be05
	ld a,(de)			;be08
	ld l,c			;be09   ; The character number times eight: where it lives in VRAM
	ld h,000h		;be0a
	add hl,hl			;be0c
	add hl,hl			;be0d
	add hl,hl			;be0e
	ld de,00000h		;be0f
	add hl,de			;be12
	ld bc,00008h		;be13   ; Eight bytes: one row of characters
	jp 04977h		;be16

; ----------------------------------------------------------------------
; DATA table_BE19: Eighteen bytes read by 0xBDD8 (0xBE19), 0xBDE3 (0xBE1F) and
;   0xBDEE (0xBE25), in groups of six.
;   0xbe19..0xbe2b  (18 bytes)
DATA_table_BE19:
	defb 070h,050h,040h,000h,040h,050h	; be19
	defb 0f0h,0b0h,0a0h,000h,0a0h,0b0h	; be1f
	defb 090h,080h,060h,000h,060h,080h	; be25

; ======================================================================
; CODE 0xbe2b..0xbe62  (55 bytes)
; ======================================================================



; ----------------------------------------------------------------------
; AND SEVEN CELLS THAT CHANGE CHARACTER
; The other background trick: seven eight-byte cards at 0xE710, each one
; with the VRAM address of a map cell. Every so many frames another
; character from the list 0xF0, 0xF2, 0xF4, 0xF2 is written over it, and
; the next one over the cell below (0x20 bytes further on). Two cells per
; card, and not a single object involved.
; ----------------------------------------------------------------------
animate_seven_cells:		; Seven eight-byte cards at 0xE710, each one with its map cell
	ld b,007h		;be2b   ; Seven cards
	ld hl,0e710h		;be2d
L_BE30:
	push bc			;be30
	push hl			;be31
	call animate_cell		;be32
	pop hl			;be35
	pop bc			;be36
	ld de,00008h		;be37   ; Eight bytes per card
	add hl,de			;be3a
	djnz L_BE30		;be3b
	ret			;be3d
animate_cell:		; Writes into its cell the character that is due, and the next one into the cell below
	dec (hl)			;be3e   ; The frames it has left
	ret nz			;be3f
	inc hl			;be40
	ld a,(hl)			;be41   ; Reloaded from the byte next to it
	dec hl			;be42
	ld (hl),a			;be43
	inc hl			;be44
	inc hl			;be45
	ld a,(hl)			;be46   ; The next drawing, four of them round and round
	inc a			;be47
	and 003h		;be48
	ld (hl),a			;be4a
	ld de,0be62h		;be4b   ; The list at 0xBE62
	call 04062h		;be4e
	ld a,(de)			;be51
	inc hl			;be52
	ld e,(hl)			;be53   ; The VRAM address of its cell
	inc hl			;be54
	ld d,(hl)			;be55
	ex de,hl			;be56
	call 0004dh		;be57   ; BIOS WRTVRM - Writes data in VRAM
	ld de,00020h		;be5a   ; And 0x20 further on, the one below
	add hl,de			;be5d
	inc a			;be5e
	jp 0004dh		;be5f   ; BIOS WRTVRM - Writes data in VRAM

; ----------------------------------------------------------------------
; DATA table_BE62: Four bytes (0xF0, 0xF2, 0xF4, 0xF2) read by 0xBE4B with `ld
;   de,0xBE62`.
;   0xbe62..0xbe66  (4 bytes)
DATA_table_BE62:
	defb 0f0h,0f2h,0f4h,0f2h	; be62

; ----------------------------------------------------------------------
; DATA filler: 0xFF filler: the gap left between the bank's last data and the
;   Konami mark.
;   0xbe66..0xbff5  (399 bytes)
DATA_filler:
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; be66  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; be76  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; be86  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; be96  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bea6  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; beb6  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bec6  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bed6  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bee6  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bef6  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bf06  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bf16  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bf26  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bf36  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bf46  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bf56  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bf66  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bf76  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bf86  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bf96  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bfa6  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bfb6  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bfc6  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bfd6  ................
	defb 0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh,0ffh	; bfe6  ...............

; ----------------------------------------------------------------------
; DATA konami_mark: The mark Konami hid at the end of the bank. Eleven bytes:
;   the eight of the title BACKWARDS (8C 82 B4 B7 92 A6 B7 87), the 0x08 that
;   says how many there are, the 0x42 that is the last two digits of the RC in
;   BCD (that is, RC-742) and the 0xAA that closes it. Read forwards and with
;   the house katakana table (index = byte minus 0x80, gojuon in order) they
;   give グラディウス: GRADIUS. The find is Manuel Pazos's (@ManuelPazosMSX).
;   0xbff5..0xc000  (11 bytes)

; ----------------------------------------------------------------------
; THE MARK KONAMI HID AT THE END OF THE BANK
; ----------------------------------------------------------------------
DATA_konami_mark:
	defb 08ch,082h,0b4h,0b7h,092h,0a6h,0b7h,087h	; bff5  ........
	defb 008h	; bffd
	defb 042h	; bffe
	defb 0aah	; bfff
